// Parse WTO data: VN import tariff (from HTTP node) + partner country tariffs (via fetch)
const rawData = $input.item.json;
const rows = [];
const API_KEY = $env.WTO_API_KEY;

// Helper: extract latest non-null value from WTO dataset
function extractLatest(dataset) {
  if (!dataset || !Array.isArray(dataset)) return null;
  let best = null;
  for (const item of dataset) {
    const rawValue = item.Value !== undefined ? item.Value : item.value;
    if (rawValue === null || rawValue === undefined || rawValue === '') continue;
    const value = parseFloat(rawValue);
    if (isNaN(value)) continue;
    const year = String(item.Year || item.Period || '0');
    if (!best || year > best.year) {
      best = { year, value };
    }
  }
  return best;
}

// 1. Vietnam's own import tariff (from HTTP node)
try {
  let dataset = [];
  if (rawData.Dataset) dataset = rawData.Dataset;
  else if (Array.isArray(rawData)) dataset = rawData;
  else if (rawData.value) dataset = rawData.value;

  const latest = extractLatest(dataset);
  if (latest) {
    rows.push({
      source: 'WTO', commodity: 'Agricultural Products',
      metric: 'vn_import_tariff_mfn', value: latest.value,
      unit: '%', period: latest.year
    });
  }
} catch (e) {}

// 2. Partner country tariffs (= export barriers for VN farmers)
const partners = [
  { code: '156', name: 'China' },
  { code: '840', name: 'USA' },
  { code: '392', name: 'Japan' },
  { code: '410', name: 'Korea' },
  { code: '608', name: 'Philippines' },
  { code: '918', name: 'EU' }
];

for (const p of partners) {
  try {
    const url = `https://api.wto.org/timeseries/v1/data?i=TP_A_0160&r=${p.code}&ps=2015,2016,2017,2018,2019,2020,2021,2022,2023,2024&fmt=json&mode=full&lang=1`;
    const response = await fetch(url, {
      headers: { 'Ocp-Apim-Subscription-Key': API_KEY }
    });
    const data = await response.json();
    const dataset = data.Dataset || (Array.isArray(data) ? data : []);
    const latest = extractLatest(dataset);
    if (latest) {
      rows.push({
        source: 'WTO', commodity: 'Agricultural Products',
        metric: `${p.name.toLowerCase()}_import_tariff_mfn`,
        value: latest.value, unit: '%', period: latest.year
      });
    }
  } catch (e) { /* skip partner */ }
}

if (rows.length === 0) {
  rows.push({ source: 'WTO', commodity: 'Agricultural Products',
    metric: 'no_data', value: 0, unit: '%', period: 'N/A' });
}

return rows.map(r => ({ json: r }));
